import React, { useEffect, useState } from "react";

export default function UserHistory({ onCancel }) {
  const [combinedHistory, setCombinedHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    setLoading(true);
    setMessage("");

    try {
      const [withdrawRes, depositRes] = await Promise.all([
        fetch("http://localhost:8080/api/withdraw/history", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }),
        fetch("http://localhost:8080/api/deposit/my-history", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }),
      ]);

      if (!withdrawRes.ok || !depositRes.ok) {
        throw new Error("ডেটা লোড করা যায়নি");
      }

      const [withdrawData, depositData] = await Promise.all([
        withdrawRes.json(),
        depositRes.json(),
      ]);

      const formatStatus = (status) =>
        status === "APPROVED" ? "COMPLETED" : status;

      const formattedWithdraws = withdrawData.map((item) => ({
        ...item,
        type: "Withdraw",
        date: item.requestedAt,
        number: item.receiverNumber,
        status: formatStatus(item.status),
      }));

      const formattedDeposits = depositData.map((item) => ({
        ...item,
        type: "Deposit",
        date: item.requestedAt,
        number: item.senderNumber,
        status: formatStatus(item.status),
      }));

      const combined = [...formattedWithdraws, ...formattedDeposits].sort(
        (a, b) => new Date(b.date) - new Date(a.date)
      );

      setCombinedHistory(combined);
    } catch (err) {
      console.error(err);
      setMessage("হিস্টোরি লোড করা যায়নি।");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.headerRow}>
        <h2 style={styles.title}>আমার ট্রানজেকশন হিস্টোরি</h2>
        <button onClick={onCancel} style={styles.backBtn}>
          ← ফিরে যান
        </button>
      </div>

      {loading ? (
        <p style={styles.loading}>লোড হচ্ছে...</p>
      ) : message ? (
        <p style={styles.error}>{message}</p>
      ) : combinedHistory.length === 0 ? (
        <p style={styles.noData}>কোনো হিস্টোরি পাওয়া যায়নি।</p>
      ) : (
        <div style={styles.tableWrapper}>
          <table style={styles.table}>
            <thead>
              <tr>
                <th>ID</th>
                <th>টাইপ</th>
                <th>ট্রানজেকশন আইডি</th>
                <th>পেমেন্ট পদ্ধতি</th>
                <th>নম্বর</th>
                <th>অ্যামাউন্ট</th>
                <th>স্ট্যাটাস</th>
                <th>তারিখ</th>
              </tr>
            </thead>
            <tbody>
              {combinedHistory.map((item) => (
                <tr key={`${item.type}-${item.id}`}>
                  <td>{item.id}</td>
                  <td>
                    {item.type === "Deposit" ? "💰 Deposit" : "🧾 Withdraw"}
                  </td>
                  <td>{item.transactionId}</td>
                  <td>{item.method}</td>
                  <td>{item.number}</td>
                  <td>৳ {Number(item.amount).toFixed(2)}</td>
                  <td>
                    <span
                      style={{
                        ...styles.status,
                        ...styles[`status_${item.status}`],
                      }}
                    >
                      {item.status}
                    </span>
                  </td>
                  <td>{new Date(item.date).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

const styles = {
  container: {
    maxWidth: "1000px",
    margin: "40px auto",
    padding: "20px",
    backgroundColor: "#ffffff",
    borderRadius: "12px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
  },
  headerRow: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "20px",
  },
  title: {
    fontSize: "24px",
    color: "#333",
    margin: 0,
  },
  backBtn: {
    padding: "8px 16px",
    backgroundColor: "#007bff",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
  },
  loading: {
    textAlign: "center",
    color: "#666",
  },
  error: {
    color: "red",
    textAlign: "center",
  },
  noData: {
    textAlign: "center",
    color: "#888",
  },
  tableWrapper: {
    overflowX: "auto",
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
    minWidth: "900px",
  },
  status: {
    padding: "4px 8px",
    borderRadius: "4px",
    fontWeight: "bold",
    color: "white",
    fontSize: "13px",
    display: "inline-block",
  },
  status_PENDING: {
    backgroundColor: "#ffc107",
  },
  status_REJECTED: {
    backgroundColor: "#dc3545",
  },
  status_COMPLETED: {
    backgroundColor: "#007bff",
  },
};
